51	
52	template <typename T>
53	__aicore__ inline RoundMode OutputCastMode()
54	{
55	    if constexpr (std::is_same_v<T, bfloat16_t>) {
56	        return RoundMode::CAST_ROUND;
57	    }
58	    return RoundMode::CAST_NONE;
59	}
60	
61	template <typename T>
62	__aicore__ inline void CastInputToFp32(
63	    LocalTensor<float> &dst,
64	    const LocalTensor<T> &src,
65	    TBuf<TPosition::VECCALC> &castBuf,
66	    int32_t count)
67	{
68	    if constexpr (std::is_same_v<T, float>) {
69	        dst = src.template ReinterpretCast<float>();
70	    } else {
71	        dst = castBuf.Get<float>();
72	        Cast(dst, src, RoundMode::CAST_NONE, count);
73	        PipeBarrier<PIPE_V>();
74	    }
75	}
76	
77	template <typename T>
78	__aicore__ inline void CastFp32ToOutput(
79	    LocalTensor<T> &dst,
80	    const LocalTensor<float> &src,
81	    int32_t count)
82	{
83	    if constexpr (!std::is_same_v<T, float>) {
84	        Cast(dst, src, OutputCastMode<T>(), count);
85	        PipeBarrier<PIPE_V>();
86	    }
87	}
