89	// ---------------------------------------------------------------------------
90	// RotaryMul Kernel
91	// ---------------------------------------------------------------------------
92	
93	template <typename dataType>
94	class KernelRotaryMul {
95	public:
96	    __aicore__ inline void Init(
97	        GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
98	        int64_t total_rows, int64_t D, int64_t half_d,
99	        int64_t rows_per_core, int64_t ub_tile_rows,
100	        int64_t rotary_mode)
101	    {
102	        totalRows_ = total_rows;
103	        D_ = D;
104	        halfD_ = half_d;
105	        rowsPerCore_ = rows_per_core;
106	        ubTileRows_ = ub_tile_rows;
107	        rotaryMode_ = rotary_mode;
108	
109	        coreIdx_ = static_cast<int64_t>(GetBlockIdx());
110	        rowStart_ = coreIdx_ * rowsPerCore_;
111	        rowEnd_ = (rowStart_ + rowsPerCore_ > totalRows_)
112	                    ? totalRows_ : (rowStart_ + rowsPerCore_);
113	        curCoreRows_ = rowEnd_ - rowStart_;
114	
115	        // Bind GM tensors
116	        int64_t totalElems = totalRows_ * D_;
117	        inputGm_.SetGlobalBuffer(
118	            reinterpret_cast<__gm__ dataType *>(input),
119	            static_cast<uint64_t>(totalElems));
120	        r1Gm_.SetGlobalBuffer(
121	            reinterpret_cast<__gm__ dataType *>(r1),
122	            static_cast<uint64_t>(totalElems));
123	        r2Gm_.SetGlobalBuffer(
124	            reinterpret_cast<__gm__ dataType *>(r2),
125	            static_cast<uint64_t>(totalElems));
126	        outputGm_.SetGlobalBuffer(
127	            reinterpret_cast<__gm__ dataType *>(output),
128	            static_cast<uint64_t>(totalElems));
129	
130	        // Initialize UB buffers
131	        int64_t tileElems = ubTileRows_ * D_;
132	        int64_t tileHalfElems = ubTileRows_ * halfD_;
133	
134	        pipe.InitBuffer(inQueue_, BUFFER_NUM,
135	                        static_cast<uint32_t>(tileElems * sizeof(dataType)));
136	        pipe.InitBuffer(outQueue_, BUFFER_NUM,
137	                        static_cast<uint32_t>(tileElems * sizeof(dataType)));
138	
139	        // FP32 compute buffers
140	        pipe.InitBuffer(inpFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
141	        pipe.InitBuffer(r1Fp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
142	        pipe.InitBuffer(r2Fp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
143	        pipe.InitBuffer(rotFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
144	
145	        // Cast buffer (shared for all casts)
146	        if constexpr (!std::is_same_v<dataType, float>) {
147	            pipe.InitBuffer(castBuf_, static_cast<uint32_t>(tileElems * sizeof(float)));
148	        }
149	
150	        // Auxiliary buffers for interleave mode
151	        if (rotaryMode_ == 1) {
152	            pipe.InitBuffer(evenBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
153	            pipe.InitBuffer(oddBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
154	        }
155	    }
156	
157	    __aicore__ inline void Process()
158	    {
159	        if (curCoreRows_ <= 0) { return; }
160	
161	        int64_t numTiles = (curCoreRows_ + ubTileRows_ - 1) / ubTileRows_;
162	
163	        for (int64_t tileIdx = 0; tileIdx < numTiles; ++tileIdx) {
164	            int64_t tileStart = tileIdx * ubTileRows_;
165	            int64_t tileEnd = (tileStart + ubTileRows_ > curCoreRows_)
166	                                ? curCoreRows_ : (tileStart + ubTileRows_);
167	            int32_t curRows = static_cast<int32_t>(tileEnd - tileStart);
168	            int32_t curElems = curRows * static_cast<int32_t>(D_);
169	            int32_t curHalfElems = curRows * static_cast<int32_t>(halfD_);
170	            int64_t globalOffset = (rowStart_ + tileStart) * D_;
171	
172	            CopyIn(globalOffset, curElems, curRows);
173	            Compute(curRows, curElems, curHalfElems, globalOffset);
174	            CopyOut(globalOffset, curElems, curRows);
175	        }
176	    }
177	
178	private:
179	    // ------------------------------------------------------------------
180	    // CopyIn: load input tile from GM to UB, cast to FP32
181	    // ------------------------------------------------------------------
182	    __aicore__ inline void CopyIn(
183	        int64_t globalOffset, int32_t curElems, int32_t curRows)
184	    {
185	        // Load input
186	        {
187	            LocalTensor<dataType> inTemp = inQueue_.AllocTensor<dataType>();
188	            LoadGmToUb(inTemp, inputGm_[globalOffset], curElems);
189	            inQueue_.EnQue(inTemp);
190	            LocalTensor<dataType> inDeq = inQueue_.DeQue<dataType>();
191	            CastInputToFp32(inpFp32Local_, inDeq, castBuf_, curElems);
192	            inQueue_.FreeTensor(inDeq);
193	        }
194	        PipeBarrier<PIPE_ALL>();
195	
196	        // Load r1
197	        {
198	            LocalTensor<dataType> r1Temp = inQueue_.AllocTensor<dataType>();
199	            LoadGmToUb(r1Temp, r1Gm_[globalOffset], curElems);
200	            inQueue_.EnQue(r1Temp);
201	            LocalTensor<dataType> r1Deq = inQueue_.DeQue<dataType>();
202	            CastInputToFp32(r1Fp32Local_, r1Deq, castBuf_, curElems);
203	            inQueue_.FreeTensor(r1Deq);
204	        }
205	        PipeBarrier<PIPE_ALL>();
206	
207	        // Load r2
208	        {
209	            LocalTensor<dataType> r2Temp = inQueue_.AllocTensor<dataType>();
210	            LoadGmToUb(r2Temp, r2Gm_[globalOffset], curElems);
211	            inQueue_.EnQue(r2Temp);
212	            LocalTensor<dataType> r2Deq = inQueue_.DeQue<dataType>();
213	            CastInputToFp32(r2Fp32Local_, r2Deq, castBuf_, curElems);
214	            inQueue_.FreeTensor(r2Deq);
215	        }
216	        PipeBarrier<PIPE_ALL>();
217	
218	        // Get FP32 TBuf pointers
219	        inpFp32Local_ = inpFp32Buf_.Get<float>();
220	        r1Fp32Local_ = r1Fp32Buf_.Get<float>();
221	        r2Fp32Local_ = r2Fp32Buf_.Get<float>();
222	        rotFp32Local_ = rotFp32Buf_.Get<float>();
223	    }
224	
225	    // ------------------------------------------------------------------
226	    // Compute: build rotated, compute output = input*r1 + rotated*r2
227	    // ------------------------------------------------------------------
228	    __aicore__ inline void Compute(
229	        int32_t curRows, int32_t curElems, int32_t curHalfElems,
230	        int64_t globalOffset)
231	    {
232	        if (rotaryMode_ == 0) {
233	            ComputeHalfMode(curRows, curElems, curHalfElems, globalOffset);
234	        } else {
235	            ComputeInterleaveMode(curRows, curElems, curHalfElems);
236	        }
237	        PipeBarrier<PIPE_ALL>();
238	    }
239	
240	    // ------------------------------------------------------------------
241	    // Half mode: rotated = concat(-input[halfD:], input[:halfD])
242	    // ------------------------------------------------------------------
243	    __aicore__ inline void ComputeHalfMode(
244	        int32_t curRows, int32_t curElems, int32_t curHalfElems,
245	        int64_t globalOffset)
246	    {
247	        int32_t D32 = static_cast<int32_t>(D_);
248	        int32_t halfD32 = static_cast<int32_t>(halfD_);
249	
250	        // Build rotated from input GM directly (avoids UB-to-UB slice issues)
251	        // First half of rotated = -input[halfD:]
252	        {
253	            LocalTensor<dataType> inpTemp = inQueue_.AllocTensor<dataType>();
254	            LoadGmToUb(inpTemp,
255	                       inputGm_[globalOffset + halfD32],
256	                       curHalfElems);
257	            inQueue_.EnQue(inpTemp);
258	            LocalTensor<dataType> inpDeq = inQueue_.DeQue<dataType>();
259	            LocalTensor<float> castTmp;
260	            CastInputToFp32(castTmp, inpDeq, castBuf_, curHalfElems);
261	            inQueue_.FreeTensor(inpDeq);
262	            // Negate
263	            Muls(rotFp32Local_, castTmp, -1.0f, curHalfElems);
264	            PipeBarrier<PIPE_V>();
265	        }
266	
267	        // Second half of rotated = input[:halfD]
268	        {
269	            LocalTensor<dataType> inpTemp = inQueue_.AllocTensor<dataType>();
270	            LoadGmToUb(inpTemp,
271	                       inputGm_[globalOffset],
272	                       curHalfElems);
273	            inQueue_.EnQue(inpTemp);
274	            LocalTensor<dataType> inpDeq = inQueue_.DeQue<dataType>();
275	            LocalTensor<float> castTmp;
276	            CastInputToFp32(castTmp, inpDeq, castBuf_, curHalfElems);
277	            inQueue_.FreeTensor(inpDeq);
278	
279	            // Use DataCopy with element count for UB-to-UB copy
280	            // Write to rotFp32Local_[halfD32:]
281	            LocalTensor<float> rotSecondHalf = rotFp32Local_[halfD32];
282	            DataCopy(rotSecondHalf, castTmp, static_cast<uint32_t>(curHalfElems));
283	            PipeBarrier<PIPE_V>();
284	        }
285	
286	        // Compute: output = input * r1 + rotated * r2
287	        Mul(r1Fp32Local_, inpFp32Local_, r1Fp32Local_, curElems);
288	        PipeBarrier<PIPE_V>();
289	        Mul(r2Fp32Local_, rotFp32Local_, r2Fp32Local_, curElems);
290	        PipeBarrier<PIPE_V>();
291	        Add(rotFp32Local_, r1Fp32Local_, r2Fp32Local_, curElems);
292	        PipeBarrier<PIPE_V>();
293	    }
294	
295	    // ------------------------------------------------------------------
296	    // Interleave mode: GatherMask extract + negate + merge
297	    // ------------------------------------------------------------------
298	    __aicore__ inline void ComputeInterleaveMode(
299	        int32_t curRows, int32_t curElems, int32_t curHalfElems)
300	    {
301	        int32_t halfD32 = static_cast<int32_t>(halfD_);
302	        int32_t D32 = static_cast<int32_t>(D_);
303	
304	        LocalTensor<float> evenTmp = evenBuf_.Get<float>();
305	        LocalTensor<float> oddTmp = oddBuf_.Get<float>();
306	
307	        // Extract even elements (indices 0,2,...) = pattern "P0101"
308	        GatherMask(evenTmp, inpFp32Local_, "0101");
309	        PipeBarrier<PIPE_V>();
310	
311	        // Extract odd elements (indices 1,3,...) = pattern "P1010"
312	        GatherMask(oddTmp, inpFp32Local_, "1010");
313	        PipeBarrier<PIPE_V>();
314	
315	        // Negate odds
316	        Muls(oddTmp, oddTmp, -1.0f, curHalfElems);
317	        PipeBarrier<PIPE_V>();
318	
319	        // Merge: rotFp32[2*i] = oddTmp[i], rotFp32[2*i+1] = evenTmp[i]
320	        // Since D is small (<=128), and we need strided write access
321	        // which has no direct vector API, use element-wise merge.
322	        for (int32_t r = 0; r < curRows; ++r) {
323	            int32_t rowOffD = r * D32;
324	            int32_t rowOffHalf = r * halfD32;
325	            for (int32_t i = 0; i < halfD32; ++i) {
326	                rotFp32Local_(rowOffD + 2 * i) = oddTmp(rowOffHalf + i);
327	                rotFp32Local_(rowOffD + 2 * i + 1) = evenTmp(rowOffHalf + i);
328	            }
329	        }
330	        PipeBarrier<PIPE_ALL>();
331	
332	        // Compute: output = input * r1 + rotated * r2
333	        Mul(r1Fp32Local_, inpFp32Local_, r1Fp32Local_, curElems);
334	        PipeBarrier<PIPE_V>();
335	        Mul(r2Fp32Local_, rotFp32Local_, r2Fp32Local_, curElems);
336	        PipeBarrier<PIPE_V>();
337	        Add(rotFp32Local_, r1Fp32Local_, r2Fp32Local_, curElems);
338	        PipeBarrier<PIPE_V>();
339	    }
340	
341	    // ------------------------------------------------------------------
342	    // CopyOut: cast to output dtype, write to GM
343	    // ------------------------------------------------------------------
344	    __aicore__ inline void CopyOut(
345	        int64_t globalOffset, int32_t curElems, int32_t curRows)
346	    {
347	        // rotFp32Local_ holds the result in FP32
348	        LocalTensor<dataType> outTemp = outQueue_.AllocTensor<dataType>();
349	
350	        if constexpr (std::is_same_v<dataType, float>) {
351	            // Direct copy: results are already fp32, just copy
352	            DataCopyExtParams cp{1, static_cast<uint32_t>(curElems * sizeof(float)), 0, 0, 0};
353	            DataCopy(outTemp.template ReinterpretCast<float>(),
354	                     rotFp32Local_, cp);
355	        } else {
356	            // Cast fp32 → output dtype
357	            CastFp32ToOutput(outTemp, rotFp32Local_, curElems);
358	        }
359	
360	        outQueue_.EnQue(outTemp);
361	        LocalTensor<dataType> outDeq = outQueue_.DeQue<dataType>();
362	        StoreUbToGm(outputGm_[globalOffset], outDeq, curElems);
363	        outQueue_.FreeTensor(outDeq);
364	        PipeBarrier<PIPE_ALL>();
365	    }
366	
367	    // Parameters
368	    int64_t totalRows_ = 0;
369	    int64_t D_ = 0;
370	    int64_t halfD_ = 0;
371	    int64_t rowsPerCore_ = 0;
372	    int64_t ubTileRows_ = 0;
373	    int64_t rotaryMode_ = 0;
374	    int64_t coreIdx_ = 0;
375	    int64_t rowStart_ = 0;
376	    int64_t rowEnd_ = 0;
377	    int64_t curCoreRows_ = 0;
378	
379	    // GM tensors
380	    GlobalTensor<dataType> inputGm_;
381	    GlobalTensor<dataType> r1Gm_;
382	    GlobalTensor<dataType> r2Gm_;
383	    GlobalTensor<dataType> outputGm_;
384	
385	    // Pipe and Queues
386	    TPipe pipe;
387	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue_;
388	    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue_;
389	
390	    // TBufs for compute (FP32)
391	    TBuf<TPosition::VECCALC> inpFp32Buf_;
392	    TBuf<TPosition::VECCALC> r1Fp32Buf_;
393	    TBuf<TPosition::VECCALC> r2Fp32Buf_;
394	    TBuf<TPosition::VECCALC> rotFp32Buf_;
395	    TBuf<TPosition::VECCALC> castBuf_;      // for fp16/bf16 casts
396	    TBuf<TPosition::VECCALC> evenBuf_;      // for interleave even extraction
397	    TBuf<TPosition::VECCALC> oddBuf_;       // for interleave odd extraction
398	
399	    // Local tensors
400	    LocalTensor<float> inpFp32Local_;
401	    LocalTensor<float> r1Fp32Local_;
402	    LocalTensor<float> r2Fp32Local_;
403	    LocalTensor<float> rotFp32Local_;
404	};
