406	// =========================================================================
407	// Dtype dispatch helper
408	// =========================================================================
409	
410	template <typename... ExtraArgs>
411	__aicore__ inline void DispatchRotaryMul(
412	    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
413	    int64_t total_rows, int64_t D, int64_t half_d,
414	    int64_t rows_per_core, int64_t ub_tile_rows,
415	    int64_t rotary_mode, int64_t dtype_flag)
416	{
417	    if (dtype_flag == 0) {
418	        KernelRotaryMul<float> kernel;
419	        kernel.Init(input, r1, r2, output,
420	                    total_rows, D, half_d,
421	                    rows_per_core, ub_tile_rows,
422	                    rotary_mode);
423	        kernel.Process();
424	    } else if (dtype_flag == 1) {
425	        KernelRotaryMul<half> kernel;
426	        kernel.Init(input, r1, r2, output,
427	                    total_rows, D, half_d,
428	                    rows_per_core, ub_tile_rows,
429	                    rotary_mode);
430	        kernel.Process();
431	    } else {
432	        KernelRotaryMul<bfloat16_t> kernel;
433	        kernel.Init(input, r1, r2, output,
434	                    total_rows, D, half_d,
435	                    rows_per_core, ub_tile_rows,
436	                    rotary_mode);
437	        kernel.Process();
438	    }
439	}
