441	// =========================================================================
442	// Kernel entry points — one per dtype
443	// dtype_flag: 0=fp32, 1=fp16, 2=bf16
444	// =========================================================================
445	
446	extern "C" __global__ __aicore__ void rotary_mul(
447	    GM_ADDR input, GM_ADDR r1, GM_ADDR r2, GM_ADDR output,
448	    int64_t total_rows, int64_t D, int64_t half_d,
449	    int64_t rows_per_core, int64_t ub_tile_rows,
450	    int64_t rotary_mode, int64_t dtype_flag)
451	{
452	    DispatchRotaryMul(
453	        input, r1, r2, output,
454	        total_rows, D, half_d,
455	        rows_per_core, ub_tile_rows,
456	        rotary_mode, dtype_flag);
457	}
