21	// Helper: integer ceil division
22	// ---------------------------------------------------------------------------
23	
24	static inline int64_t CeilDiv(int64_t a, int64_t b)
25	{
26	    if (b <= 0) { return 0; }
27	    return (a + b - 1) / b;
28	}
