30	// ---------------------------------------------------------------------------
31	// Host function: npu_rotary_mul
32	// ---------------------------------------------------------------------------
33	
34	at::Tensor rotary_mul(
35	    const at::Tensor &input,
36	    const at::Tensor &r1,
37	    const at::Tensor &r2,
38	    std::string rotary_mode)
39	{
40	    // --- Input validation ---
41	    TORCH_CHECK(input.dim() == 4,
42	                "rotary_mul: input must be 4D (B, H, S, D)");
43	    TORCH_CHECK(input.scalar_type() == r1.scalar_type() &&
44	                input.scalar_type() == r2.scalar_type(),
45	                "rotary_mul: input, r1, r2 must have same dtype");
46	    TORCH_CHECK(input.is_contiguous() && r1.is_contiguous() && r2.is_contiguous(),
47	                "rotary_mul: all inputs must be contiguous");
48	
49	    int64_t B = input.size(0);
50	    int64_t H = input.size(1);
51	    int64_t S = input.size(2);
52	    int64_t D = input.size(3);
53	
54	    TORCH_CHECK(D % 2 == 0, "rotary_mul: last dimension D must be even");
55	
56	    int64_t total_rows = B * H * S;
57	    int64_t total_elements = total_rows * D;
58	    int64_t half_d = D / 2;
59	
60	    // --- Dtype flag ---
61	    int64_t dtype_flag = 0;  // fp32
62	    if (input.scalar_type() == at::kHalf) {
63	        dtype_flag = 1;
64	    } else if (input.scalar_type() == at::kBFloat16) {
65	        dtype_flag = 2;
66	    }
67	
68	    // --- Rotary mode flag ---
69	    int64_t rotary_mode_flag = (rotary_mode == "interleave") ? 1 : 0;
70	
71	    // --- Platform info ---
72	    auto ascendcPlatform = platform_ascendc::PlatformAscendCMgr::GetInstance();
73	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
74	    if (coreNum <= 0) { coreNum = 32; }
75	
76	    // --- UB tile size calculation ---
77	    uint64_t ubSize = 0;
78	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
79	
80	    // UB budget: we need buffers for:
81	    //   inp_fp32, r1_fp32, r2_fp32, rot_fp32 (4x tile_rows * D * 4)
82	    //   + inQueue, outQueue (2x tile_rows * D * sizeof(dataType))
83	    //   + castBuf (if not fp32), evenBuf, oddBuf (if interleave)
84	    int64_t elemBytes = (dtype_flag == 0) ? 4 : 2;
85	    int64_t fp32PerElem = 4;
86	    int64_t numTbufs = (dtype_flag == 0) ? 4 : 5;
87	    if (rotary_mode_flag == 1) { numTbufs += 2; }
88	
89	    // Max tile rows from UB: ubSize >= numTbufs * tile_rows * D * 4 + 2 * tile_rows * D * elemBytes
90	    // Simplification: ubSize >= tile_rows * D * (numTbufs * 4 + 2 * elemBytes)
91	    int64_t ubBudgetPerRow = D * (numTbufs * fp32PerElem + 2 * elemBytes);
92	    int64_t maxTileRows = static_cast<int64_t>(static_cast<double>(ubSize) * 0.85 / ubBudgetPerRow);
93	    // Clamp and align
94	    int64_t ub_tile_rows = std::min<int64_t>(128, std::max<int64_t>(16, maxTileRows));
95	    ub_tile_rows = (ub_tile_rows / 16) * 16;
96	    if (ub_tile_rows < 16) { ub_tile_rows = 16; }
97	
98	    // --- Core-level tiling ---
99	    int64_t usedCoreNum = std::min(coreNum, CeilDiv(total_rows, ub_tile_rows));
100	    if (usedCoreNum < 1) { usedCoreNum = 1; }
101	    int64_t rows_per_core = CeilDiv(total_rows, usedCoreNum);
102	
103	    // --- Output allocation ---
104	    at::Tensor output = at::empty_like(input);
105	
106	    // --- EXEC_KERNEL_CMD: all parameters must be left-values ---
107	    int64_t total_rows_lv = total_rows;
108	    int64_t D_lv = D;
109	    int64_t half_d_lv = half_d;
110	    int64_t rows_per_core_lv = rows_per_core;
111	    int64_t ub_tile_rows_lv = ub_tile_rows;
112	    int64_t rotary_mode_lv = rotary_mode_flag;
113	    int64_t dtype_flag_lv = dtype_flag;
114	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
115	
116	    EXEC_KERNEL_CMD(rotary_mul, blockDim,
117	                    input, r1, r2, output,
118	                    total_rows_lv, D_lv, half_d_lv,
119	                    rows_per_core_lv, ub_tile_rows_lv,
120	                    rotary_mode_lv, dtype_flag_lv);
121	
122	    return output;
123	}
124	
125	}  // namespace ascend_kernel
