// AscendC InterleaveRope kernel
// Operator: npu_interleave_rope (Interleave Rotary Position Embedding)
// Computes:
//   1. Interleave x: gather even elements first, then odd elements
//   2. x_rotated = concat(-x_odd, x_even)
//   3. output = x_interleaved * cos + x_rotated * sin
//   4. Cast back to original dtype
//
// All compute in FP32 for numerical stability.
// Pure Vector operator, no Cube.

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Data movement helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    LocalTensor<T> &dst,
    const GlobalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const GlobalTensor<T> &dst,
    const LocalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPad(dst, src, copyParams);
}

// ---------------------------------------------------------------------------
// Cast helpers for FP16/BF16 → FP32 → FP16/BF16
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline RoundMode OutputCastMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return RoundMode::CAST_ROUND;
    }
    return RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void CastInputToFp32(
    LocalTensor<float> &dst,
    const LocalTensor<T> &src,
    TBuf<TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        Cast(dst, src, RoundMode::CAST_NONE, count);
        PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void CastFp32ToOutput(
    LocalTensor<T> &dst,
    const LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        Cast(dst, src, OutputCastMode<T>(), count);
        PipeBarrier<PIPE_V>();
    }
}

// ---------------------------------------------------------------------------
// InterleaveRope Kernel
// ---------------------------------------------------------------------------

template <typename dataType>
class KernelInterleaveRope {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR output,
        int64_t total_rows, int64_t D, int64_t half_d,
        int64_t rows_per_core, int64_t ub_tile_rows)
    {
        totalRows_ = total_rows;
        D_ = D;
        halfD_ = half_d;
        rowsPerCore_ = rows_per_core;
        ubTileRows_ = ub_tile_rows;

        coreIdx_ = static_cast<int64_t>(GetBlockIdx());
        rowStart_ = coreIdx_ * rowsPerCore_;
        rowEnd_ = (rowStart_ + rowsPerCore_ > totalRows_)
                    ? totalRows_ : (rowStart_ + rowsPerCore_);
        curCoreRows_ = rowEnd_ - rowStart_;

        int64_t totalElems = totalRows_ * D_;
        int64_t D32 = static_cast<int32_t>(D_);

        // Bind GM tensors (all flat 1D: total_rows * D elements)
        xGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(x),
            static_cast<uint64_t>(totalElems));
        cosGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(cos),
            static_cast<uint64_t>(totalElems));
        sinGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(sin),
            static_cast<uint64_t>(totalElems));
        outputGm_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(output),
            static_cast<uint64_t>(totalElems));

        // UB tile element counts
        int64_t tileElems = ubTileRows_ * D_;
        int64_t tileHalfElems = ubTileRows_ * halfD_;

        // Queues
        pipe.InitBuffer(inQueue_, BUFFER_NUM,
                        static_cast<uint32_t>(tileElems * sizeof(dataType)));
        pipe.InitBuffer(outQueue_, BUFFER_NUM,
                        static_cast<uint32_t>(tileElems * sizeof(dataType)));

        // FP32 compute buffers
        pipe.InitBuffer(xFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        pipe.InitBuffer(cosFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        pipe.InitBuffer(sinFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        pipe.InitBuffer(outFp32Buf_, static_cast<uint32_t>(tileElems * sizeof(float)));

        // GatherMask output buffers (even/odd halves)
        pipe.InitBuffer(evenBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
        pipe.InitBuffer(oddBuf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));

        // Temporary compute buffers
        pipe.InitBuffer(tmp1Buf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));
        pipe.InitBuffer(tmp2Buf_, static_cast<uint32_t>(tileHalfElems * sizeof(float)));

        // Cast buffer
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(castBuf_, static_cast<uint32_t>(tileElems * sizeof(float)));
        }
    }

    __aicore__ inline void Process()
    {
        if (curCoreRows_ <= 0) { return; }

        int64_t numTiles = (curCoreRows_ + ubTileRows_ - 1) / ubTileRows_;

        for (int64_t tileIdx = 0; tileIdx < numTiles; ++tileIdx) {
            int64_t tileStart = tileIdx * ubTileRows_;
            int64_t tileEnd = (tileStart + ubTileRows_ > curCoreRows_)
                                ? curCoreRows_ : (tileStart + ubTileRows_);
            int32_t curRows = static_cast<int32_t>(tileEnd - tileStart);
            int32_t curElems = curRows * static_cast<int32_t>(D_);
            int32_t curHalfElems = curRows * static_cast<int32_t>(halfD_);
            int64_t globalOffset = (rowStart_ + tileStart) * D_;

            CopyIn(globalOffset, curElems, curRows);
            Compute(curRows, curElems, curHalfElems, globalOffset);
            CopyOut(globalOffset, curElems, curRows);
        }
    }

private:
    // ------------------------------------------------------------------
    // CopyIn: load x, cos, sin from GM to UB, cast to FP32
    // ------------------------------------------------------------------
    __aicore__ inline void CopyIn(
        int64_t globalOffset, int32_t curElems, int32_t curRows)
    {
        // Load x
        {
            LocalTensor<dataType> temp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(temp, xGm_[globalOffset], curElems);
            inQueue_.EnQue(temp);
            LocalTensor<dataType> deq = inQueue_.DeQue<dataType>();
            CastInputToFp32(xFp32Local_, deq, castBuf_, curElems);
            inQueue_.FreeTensor(deq);
        }
        PipeBarrier<PIPE_ALL>();

        // Load cos
        {
            LocalTensor<dataType> temp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(temp, cosGm_[globalOffset], curElems);
            inQueue_.EnQue(temp);
            LocalTensor<dataType> deq = inQueue_.DeQue<dataType>();
            CastInputToFp32(cosFp32Local_, deq, castBuf_, curElems);
            inQueue_.FreeTensor(deq);
        }
        PipeBarrier<PIPE_ALL>();

        // Load sin
        {
            LocalTensor<dataType> temp = inQueue_.AllocTensor<dataType>();
            LoadGmToUb(temp, sinGm_[globalOffset], curElems);
            inQueue_.EnQue(temp);
            LocalTensor<dataType> deq = inQueue_.DeQue<dataType>();
            CastInputToFp32(sinFp32Local_, deq, castBuf_, curElems);
            inQueue_.FreeTensor(deq);
        }
        PipeBarrier<PIPE_ALL>();

        // Get TBuf pointers
        xFp32Local_ = xFp32Buf_.Get<float>();
        cosFp32Local_ = cosFp32Buf_.Get<float>();
        sinFp32Local_ = sinFp32Buf_.Get<float>();
        outFp32Local_ = outFp32Buf_.Get<float>();
    }

    // ------------------------------------------------------------------
    // Compute: interleave + RoPE rotation per row
    // ------------------------------------------------------------------
    __aicore__ inline void Compute(
        int32_t curRows, int32_t curElems, int32_t curHalfElems,
        int64_t globalOffset)
    {
        int32_t D32 = static_cast<int32_t>(D_);
        int32_t halfD32 = static_cast<int32_t>(halfD_);

        LocalTensor<float> evenTmp = evenBuf_.Get<float>();
        LocalTensor<float> oddTmp = oddBuf_.Get<float>();
        LocalTensor<float> tmp1 = tmp1Buf_.Get<float>();
        LocalTensor<float> tmp2 = tmp2Buf_.Get<float>();

        // Step 1: GatherMask to extract even/odd elements from x
        // Pattern "0101": take positions 0,2,4,... (even indices)
        // Pattern "1010": take positions 1,3,5,... (odd indices)
        GatherMask(evenTmp, xFp32Local_, "0101");
        PipeBarrier<PIPE_V>();
        GatherMask(oddTmp, xFp32Local_, "1010");
        PipeBarrier<PIPE_V>();

        // Step 2: Per-row computation
        // For each row r:
        //   x_even = evenTmp[r*half_D : (r+1)*half_D]
        //   x_odd  = oddTmp[r*half_D : (r+1)*half_D]
        //   cos_first = cosFp32Local_[r*D : r*D + half_D]
        //   cos_second = cosFp32Local_[r*D + half_D : (r+1)*D]
        //   sin_first = sinFp32Local_[r*D : r*D + half_D]
        //   sin_second = sinFp32Local_[r*D + half_D : (r+1)*D]
        //
        //   output_first  = x_even * cos_first + (-x_odd) * sin_first
        //   output_second = x_odd * cos_second + x_even * sin_second
        for (int32_t r = 0; r < curRows; ++r) {
            int32_t rowOffD = r * D32;
            int32_t rowOffHalf = r * halfD32;

            // --- Compute first half ---
            // tmp1 = x_even * cos_first
            Mul(tmp1, evenTmp[rowOffHalf], cosFp32Local_[rowOffD], halfD32);
            PipeBarrier<PIPE_V>();

            // tmp2 = -x_odd
            Muls(tmp2, oddTmp[rowOffHalf], -1.0f, halfD32);
            PipeBarrier<PIPE_V>();

            // tmp2 = (-x_odd) * sin_first
            Mul(tmp2, tmp2, sinFp32Local_[rowOffD], halfD32);
            PipeBarrier<PIPE_V>();

            // output_first = tmp1 + tmp2
            Add(outFp32Local_[rowOffD], tmp1, tmp2, halfD32);
            PipeBarrier<PIPE_V>();

            // --- Compute second half ---
            // tmp1 = x_odd * cos_second
            Mul(tmp1, oddTmp[rowOffHalf], cosFp32Local_[rowOffD + halfD32], halfD32);
            PipeBarrier<PIPE_V>();

            // tmp2 = x_even * sin_second
            Mul(tmp2, evenTmp[rowOffHalf], sinFp32Local_[rowOffD + halfD32], halfD32);
            PipeBarrier<PIPE_V>();

            // output_second = tmp1 + tmp2
            Add(outFp32Local_[rowOffD + halfD32], tmp1, tmp2, halfD32);
            PipeBarrier<PIPE_V>();
        }

        PipeBarrier<PIPE_ALL>();
    }

    // ------------------------------------------------------------------
    // CopyOut: cast to output dtype, write to GM
    // ------------------------------------------------------------------
    __aicore__ inline void CopyOut(
        int64_t globalOffset, int32_t curElems, int32_t curRows)
    {
        LocalTensor<dataType> outTemp = outQueue_.AllocTensor<dataType>();

        if constexpr (std::is_same_v<dataType, float>) {
            // Direct copy: results are already fp32
            DataCopyExtParams cp{1, static_cast<uint32_t>(curElems * sizeof(float)), 0, 0, 0};
            DataCopy(outTemp.template ReinterpretCast<float>(),
                     outFp32Local_, cp);
        } else {
            // Cast fp32 → output dtype
            CastFp32ToOutput(outTemp, outFp32Local_, curElems);
        }

        outQueue_.EnQue(outTemp);
        LocalTensor<dataType> outDeq = outQueue_.DeQue<dataType>();
        StoreUbToGm(outputGm_[globalOffset], outDeq, curElems);
        outQueue_.FreeTensor(outDeq);
        PipeBarrier<PIPE_ALL>();
    }

    // Parameters
    int64_t totalRows_ = 0;
    int64_t D_ = 0;
    int64_t halfD_ = 0;
    int64_t rowsPerCore_ = 0;
    int64_t ubTileRows_ = 0;
    int64_t coreIdx_ = 0;
    int64_t rowStart_ = 0;
    int64_t rowEnd_ = 0;
    int64_t curCoreRows_ = 0;

    // GM tensors
    GlobalTensor<dataType> xGm_;
    GlobalTensor<dataType> cosGm_;
    GlobalTensor<dataType> sinGm_;
    GlobalTensor<dataType> outputGm_;

    // Pipe and Queues
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue_;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue_;

    // TBufs for compute (FP32)
    TBuf<TPosition::VECCALC> xFp32Buf_;
    TBuf<TPosition::VECCALC> cosFp32Buf_;
    TBuf<TPosition::VECCALC> sinFp32Buf_;
    TBuf<TPosition::VECCALC> outFp32Buf_;
    TBuf<TPosition::VECCALC> evenBuf_;
    TBuf<TPosition::VECCALC> oddBuf_;
    TBuf<TPosition::VECCALC> tmp1Buf_;
    TBuf<TPosition::VECCALC> tmp2Buf_;
    TBuf<TPosition::VECCALC> castBuf_;

    // Local tensors
    LocalTensor<float> xFp32Local_;
    LocalTensor<float> cosFp32Local_;
    LocalTensor<float> sinFp32Local_;
    LocalTensor<float> outFp32Local_;
};

// =========================================================================
// Dtype dispatch helper
// =========================================================================

template <typename... ExtraArgs>
__aicore__ inline void DispatchInterleaveRope(
    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR output,
    int64_t total_rows, int64_t D, int64_t half_d,
    int64_t rows_per_core, int64_t ub_tile_rows, int64_t dtype_flag)
{
    if (dtype_flag == 0) {
        KernelInterleaveRope<float> kernel;
        kernel.Init(x, cos, sin, output,
                    total_rows, D, half_d,
                    rows_per_core, ub_tile_rows);
        kernel.Process();
    } else if (dtype_flag == 1) {
        KernelInterleaveRope<half> kernel;
        kernel.Init(x, cos, sin, output,
                    total_rows, D, half_d,
                    rows_per_core, ub_tile_rows);
        kernel.Process();
    } else {
        KernelInterleaveRope<bfloat16_t> kernel;
        kernel.Init(x, cos, sin, output,
                    total_rows, D, half_d,
                    rows_per_core, ub_tile_rows);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// dtype_flag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void interleave_rope(
    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR output,
    int64_t total_rows, int64_t D, int64_t half_d,
    int64_t rows_per_core, int64_t ub_tile_rows, int64_t dtype_flag)
{
    DispatchInterleaveRope(
        x, cos, sin, output,
        total_rows, D, half_d,
        rows_per_core, ub_tile_rows, dtype_flag);
}
