// InterleaveRope op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_interleave_rope.h"

namespace ascend_kernel {

// ---------------------------------------------------------------------------
// Helper: integer ceil division
// ---------------------------------------------------------------------------

static inline int64_t CeilDiv(int64_t a, int64_t b)
{
    if (b <= 0) { return 0; }
    return (a + b - 1) / b;
}

// ---------------------------------------------------------------------------
// Host function: npu_interleave_rope
// ---------------------------------------------------------------------------

at::Tensor interleave_rope(
    const at::Tensor &x,
    const at::Tensor &cos,
    const at::Tensor &sin)
{
    // --- Input validation ---
    TORCH_CHECK(x.dim() == 4,
                "interleave_rope: x must be 4D (B, N, S, D)");
    TORCH_CHECK(x.scalar_type() == cos.scalar_type() &&
                x.scalar_type() == sin.scalar_type(),
                "interleave_rope: x, cos, sin must have same dtype");
    TORCH_CHECK(x.is_contiguous() && cos.is_contiguous() && sin.is_contiguous(),
                "interleave_rope: all inputs must be contiguous");

    int64_t B = x.size(0);
    int64_t N = x.size(1);
    int64_t S = x.size(2);
    int64_t D = x.size(3);

    (void)B;
    (void)N;
    (void)S;

    TORCH_CHECK(D % 2 == 0, "interleave_rope: last dimension D must be even");
    TORCH_CHECK(cos.size(3) == D && sin.size(3) == D,
                "interleave_rope: cos/sin last dim must match D");
    TORCH_CHECK(cos.size(0) == B && sin.size(0) == B,
                "interleave_rope: batch dim mismatch");
    TORCH_CHECK(cos.size(1) == N && sin.size(1) == N,
                "interleave_rope: heads dim mismatch");
    TORCH_CHECK(cos.size(2) == S && sin.size(2) == S,
                "interleave_rope: seq_len dim mismatch");

    int64_t total_rows = B * N * S;
    int64_t half_d = D / 2;

    // --- Dtype flag ---
    int64_t dtype_flag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtype_flag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtype_flag = 2;
    }

    // --- Platform info ---
    auto ascendcPlatform = platform_ascendc::PlatformAscendCMgr::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) { coreNum = 32; }

    // --- UB tile size calculation ---
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // UB budget per row:
    //   Queues: 2 * D * sizeof(dataType)
    //   FP32 TBufs: x(D), cos(D), sin(D), out(D), even(D/2), odd(D/2),
    //               tmp1(D/2), tmp2(D/2) = 4*D + 4*(D/2) = 6*D fp32 elements
    //   Cast buf (if not fp32): D fp32 elements
    // Total UB per row for fp16:
    //   = 2*D*2 + (6*D + D)*4 = 4D + 28D = 32D bytes
    //   = 32 * 64 = 2048 bytes
    // For fp32:
    //   = 2*D*4 + 6*D*4 = 8D + 24D = 32D bytes
    int64_t elemBytes = (dtype_flag == 0) ? 4 : 2;
    int64_t fp32PerElem = 4;
    int64_t numFp32Tbufs = (dtype_flag == 0) ? 6 : 7;  // +1 for cast buf

    // UB budget per row: 2*D*elemBytes + numFp32Tbufs*D*fp32PerElem
    //   = D * (2*elemBytes + numFp32Tbufs*fp32PerElem)
    int64_t ubBudgetPerRow = D * (2 * elemBytes + numFp32Tbufs * fp32PerElem);
    int64_t maxTileRows = static_cast<int64_t>(static_cast<double>(ubSize) * 0.85 / ubBudgetPerRow);
    int64_t ub_tile_rows = std::min<int64_t>(128, std::max<int64_t>(1, maxTileRows));
    if (ub_tile_rows < 1) { ub_tile_rows = 1; }

    // --- Core-level tiling ---
    int64_t usedCoreNum = std::min(coreNum, CeilDiv(total_rows, ub_tile_rows));
    if (usedCoreNum < 1) { usedCoreNum = 1; }
    int64_t rows_per_core = CeilDiv(total_rows, usedCoreNum);

    // --- Output allocation ---
    at::Tensor output = at::empty_like(x);

